import java.io.*;
import java.util.*;

public class Main {
    static boolean isLucky(long x) {
        if (x <= 0) return false;
        while (x > 0) {
            long digit = x % 10;
            if (digit != 4 && digit != 7) return false;
            x /= 10;
        }
        return true;
    }

    static int countLucky(long current, long limit) {
        if (current > limit) return 0;
        return 1
                + countLucky(current * 10 + 4, limit)
                + countLucky(current * 10 + 7, limit);
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        long n = fs.nextLong();
        long k = fs.nextLong();

        int suffixSize = (int) Math.min(n, 13);

        long[] factorial = new long[suffixSize + 1];
        factorial[0] = 1;
        for (int i = 1; i <= suffixSize; i++) {
            factorial[i] = factorial[i - 1] * i;
        }

        if (factorial[suffixSize] < k) {
            System.out.println(-1);
            return;
        }

        long prefixSize = n - suffixSize;
        long answer = countLucky(4, prefixSize) + countLucky(7, prefixSize);

        List<Long> remaining = new ArrayList<>();
        for (long value = prefixSize + 1; value <= n; value++) {
            remaining.add(value);
        }

        long rank = k - 1;
        for (int position = 0; position < suffixSize; position++) {
            int remainingCount = suffixSize - position;
            long blockSize = factorial[remainingCount - 1];
            int selectedIndex = (int) (rank / blockSize);
            rank %= blockSize;

            long value = remaining.remove(selectedIndex);
            long index = prefixSize + position + 1;

            if (isLucky(index) && isLucky(value)) {
                answer++;
            }
        }

        System.out.println(answer);
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int pointer = 0;
        private int length = 0;

        FastScanner(InputStream in) {
            this.in = in;
        }

        private int read() throws IOException {
            if (pointer >= length) {
                length = in.read(buffer);
                pointer = 0;
                if (length <= 0) return -1;
            }
            return buffer[pointer++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            long value = 0;
            while (c > ' ') {
                value = value * 10 + (c - '0');
                c = read();
            }
            return value;
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {
    private static int n;
    private static final List<Integer> luckyNumbers = new ArrayList<>();

    private static void generateLucky(long value) {
        if (value > n) return;

        if (value > 0) {
            luckyNumbers.add((int) value);
        }

        generateLucky(value * 10 + 4);
        generateLucky(value * 10 + 7);
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        n = fs.nextInt();
        long k = fs.nextLong();

        int length = 1;
        long factorial = 1;

        while (factorial < k && length < n) {
            length++;
            factorial *= length;
        }

        if (factorial < k) {
            System.out.println(-1);
            return;
        }

        long[] fact = new long[length + 1];
        fact[0] = 1;
        for (int i = 1; i <= length; i++) {
            fact[i] = fact[i - 1] * i;
        }

        int start = n - length + 1;
        List<Integer> available = new ArrayList<>(length);
        for (int value = start; value <= n; value++) {
            available.add(value);
        }

        int[] permutationSuffix = new int[length];
        long rank = k - 1;

        for (int i = 0; i < length; i++) {
            long blockSize = fact[length - i - 1];
            int index = (int) (rank / blockSize);
            rank %= blockSize;
            permutationSuffix[i] = available.remove(index);
        }

        generateLucky(0);
        Set<Integer> luckySet = new HashSet<>(luckyNumbers);

        int answer = 0;
        for (int position : luckyNumbers) {
            int value;
            if (position < start) {
                value = position;
            } else {
                value = permutationSuffix[position - start];
            }

            if (luckySet.contains(value)) {
                answer++;
            }
        }

        System.out.println(answer);
    }

    private static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int pointer = 0;
        private int length = 0;

        FastScanner(InputStream in) {
            this.in = in;
        }

        private int read() throws IOException {
            if (pointer >= length) {
                length = in.read(buffer);
                pointer = 0;
                if (length <= 0) return -1;
            }
            return buffer[pointer++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            long value = 0;
            while (c > ' ') {
                value = value * 10 + (c - '0');
                c = read();
            }
            return value;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }
}

